const $=s=>document.querySelector(s);
const data=[
{id:1,title:'西岸漫步 · 把下午交给江风',cat:'户外',area:'徐汇滨江',time:'周六 15:00–18:00',price:0,indoor:false,group:4,art:'江风与日落',symbol:'↗',desc:'从龙腾大道出发，沿江步行，途中找一处草坪休息。推荐带水、穿舒适的鞋。',route:'龙腾大道 → 滨江步道 → 日落休息点'},
{id:2,title:'留白之间 · 当代艺术慢看计划',cat:'展览',area:'黄浦区艺术空间',time:'周六 10:00–17:00',price:60,indoor:true,group:1,art:'留白之间',symbol:'◯',desc:'给自己留出两小时，慢慢看一场展览。以下为艺术空间体验示例，出发前请确认真实展期与门票。',route:'艺术空间 → 周边独立书店 → 咖啡休息'},
{id:3,title:'梧桐街角 · 周末手作市集',cat:'市集',area:'长宁街区',time:'周日 11:00–18:00',price:0,indoor:false,group:2,art:'街角有好物',symbol:'✳',desc:'逛手作摊位、看独立设计，给日常找一件小物。标价为入场预算，购物另计；此为市集体验示例。',route:'街区入口 → 手作摊位 → 街边小店'},
{id:4,title:'黑胶下午茶 · 听一场小型现场',cat:'演出',area:'静安音乐空间',time:'周六 16:00–18:00',price:88,indoor:true,group:2,art:'周末的频率',symbol:'♫',desc:'一个适合放慢节奏的音乐下午。演出与价格为演示，请提前核对实际场次。',route:'音乐空间 → 现场聆听 → 晚餐自由安排'},
{id:5,title:'城市森林 · 轻徒步充电计划',cat:'户外',area:'共青森林公园周边',time:'周日 09:00–12:00',price:30,indoor:false,group:4,art:'去绿色里',symbol:'↟',desc:'轻量步行约 4 公里，不追求速度。带水、防晒与零食，雨天建议改为室内活动。预算为交通与补给估计。',route:'集合点 → 林间步道 → 草地野餐'},
{id:6,title:'书店漫游 · 偶遇一本好书',cat:'展览',area:'虹口文化街区',time:'周日 14:00–17:00',price:0,indoor:true,group:1,art:'翻到新一页',symbol:'≋',desc:'用一个下午逛书店、读几页书，写下喜欢的句子。此为自助漫游计划，不含店内消费。',route:'独立书店 → 阅读休息 → 街区散步'}];
let state={saved:[],checked:[],teams:[],stories:[]};try{Object.assign(state,JSON.parse(localStorage.getItem('weekend-wander-v1')||'{}'))}catch{};
let category='全部',view='discover';const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function persist(){try{localStorage.setItem('weekend-wander-v1',JSON.stringify(state))}catch{toast('浏览器未允许保存，本次记录将在关闭后丢失')}$('#count').textContent=state.saved.length}
let timer;function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(timer);timer=setTimeout(()=>$('#toast').style.display='none',3000)}
function results(){const rain=$('#weather').value==='rain',budget=Number($('#budget').value),people=Number($('#people').value);return data.filter(a=>(category==='全部'||a.cat===category)&&a.price<=budget&&(!rain||a.indoor)).sort((a,b)=>(Number(b.group===people)-Number(a.group===people)))}
function card(a){return `<article class="card"><button class="card-link" style="width:100%" data-detail="${a.id}" aria-label="查看${a.title}"><div class="card-art type${a.id%6}"><span class="badge">${a.cat} · ${a.indoor?'室内':'户外'}</span><span class="symbol">${a.symbol}</span><span class="art-title">${a.art}</span></div></button><div class="card-body"><button class="card-link" data-detail="${a.id}"><h3>${a.title}</h3></button><div class="meta">◎ ${a.area}<br>◷ ${a.time}</div><p class="reason">${state.checked.includes(a.id)?'✓ 已打卡 · 又收藏了一段城市记忆':$('#weather').value==='rain'?'雨天友好 · 不让天气打乱周末':a.group===Number($('#people').value)?'适合你的同行人数 · 轻松出发':a.indoor?'室内慢体验 · 放松一下':'亲近自然 · 给生活透透气'}</p><div class="card-foot"><span class="price">${a.price?'¥'+a.price:'免费'} <small>${a.price?'/ 人均预算':'/ 入场'}</small></span><button class="small-btn ${state.saved.includes(a.id)?'saved':''}" data-save="${a.id}">${state.saved.includes(a.id)?'✓ 已加入':'＋ 加入清单'}</button></div></div></article>`}
function render(){const list=results();$('#resultCount').textContent=`找到 ${list.length} 个周末灵感`;$('#cards').innerHTML=list.length?list.map(card).join(''):'<div class="empty">暂时没有符合条件的活动。<br>试试调整预算或兴趣。<p><button class="small-btn" id="reset">重置筛选</button></p></div>';$('#planCards').innerHTML=state.saved.length?data.filter(a=>state.saved.includes(a.id)).map(card).join(''):'<div class="empty">你的周末还是一张空白明信片。<br>在「发现周末」加入第一个想去的地方。</div>';$('#count').textContent=state.saved.length;renderStories()}
function navigate(v){view=v;['discover','plans','stories'].forEach(x=>$('#'+x).hidden=x!==v);document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('active',n.dataset.view===v));render()}
function save(id){state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];persist();render();toast(state.saved.includes(id)?'已加入你的周末清单':'已从清单移除')}
function detail(id){const a=data.find(a=>a.id===id);$('#detailBody').innerHTML=`<p class="eyebrow">${a.cat} / WEEKEND PLAN</p><h2>${a.title}</h2><p>${a.desc}</p><div class="detail-info">◎ ${a.area}<br>◷ ${a.time}<br>人均预算：${a.price?'¥'+a.price:'免费'}<br>建议路线：${a.route}</div><p class="muted">组队体验保存在本机，邀请链接不会自动建立多人房间。请通过分享文字与朋友确认出行。</p><div class="actions"><button class="primary" data-save="${id}">${state.saved.includes(id)?'移出清单':'加入清单'}</button><button class="small-btn" data-team="${id}">${state.teams.includes(id)?'复制组队邀请':'发起组队邀请'}</button><button class="small-btn" data-check="${id}">${state.checked.includes(id)?'撤销打卡':'我已到达 · 打卡'}</button></div>`;if(!$('#detail').open)$('#detail').showModal()}
async function copy(s){try{await navigator.clipboard.writeText(s);toast('已复制，发给朋友一起出发')}catch{const t=document.createElement('textarea');t.value=s;document.body.append(t);t.select();const ok=document.execCommand('copy');t.remove();toast(ok?'已复制分享文字':'未能复制，请在手记中手动选择文字')}}
function renderStories(){const sample=[{title:'把滨江的黄昏留给自己',text:'示例攻略\n15:00 到达滨江 → 沿江慢走 → 找一处座椅看落日。\n预算：自带饮水，交通另计。\n小贴士：天气变化时改去附近书店。'}];$('#storyList').innerHTML=[...state.stories,...sample].map((s,i)=>`<article class="story"><p class="eyebrow">${i<state.stories.length?'MY CITY NOTES · 本机手记':'EDITOR’S NOTE · 示例手记'}</p><h3>${esc(s.title)}</h3><p>${esc(s.text)}</p><button class="small-btn" data-share="${i}">复制攻略分享 ↗</button></article>`).join('')}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view)navigate(b.dataset.view);if(b.dataset.cat){category=b.dataset.cat;document.querySelectorAll('[data-cat]').forEach(x=>x.classList.toggle('selected',x===b));render()}if(b.dataset.detail)detail(+b.dataset.detail);if(b.dataset.save){save(+b.dataset.save);if($('#detail').open)detail(+b.dataset.save)}if(b.dataset.check){const id=+b.dataset.check;state.checked=state.checked.includes(id)?state.checked.filter(x=>x!==id):[...state.checked,id];if(!state.saved.includes(id))state.saved.push(id);persist();render();detail(id);toast(state.checked.includes(id)?'打卡已记录在本机':'已撤销打卡')}if(b.dataset.team){const a=data.find(a=>a.id===+b.dataset.team);if(!state.teams.includes(a.id))state.teams.push(a.id);persist();copy(`周末组队邀请｜${a.title}\n${a.time} · ${a.area}\n人均预算：¥${a.price}\n路线：${a.route}\n有兴趣一起吗？时间和真实开放情况出发前再确认。\n${location.href.split('#')[0]}#activity-${a.id}`);detail(a.id)}if(b.dataset.share){const el=b.closest('.story');copy(el.querySelector('h3').textContent+'\n'+el.querySelector('p:not(.eyebrow)').textContent)}if(b.classList.contains('close'))b.closest('dialog').close();if(b.id==='reset'){category='全部';$('#budget').value='999';$('#weather').value='sun';document.querySelector('[data-cat="全部"]').click();updateWeather()}});
function updateWeather(){$('#weatherTitle').textContent=$('#weather').value==='rain'?'下雨也有好去处，室内灵感已就位':$('#weather').value==='cloud'?'多云的周末，适合慢慢探索':'晴天，适合向外走走';render()}
$('#weather').onchange=updateWeather;$('#budget').onchange=render;$('#people').onchange=render;$('#surprise').onclick=()=>{const list=results();if(list.length)detail(list[Math.floor(Math.random()*list.length)].id);else toast('先放宽筛选，再获取灵感')};$('#write').onclick=()=>$('#editor').showModal();$('#storyForm').onsubmit=e=>{e.preventDefault();const title=$('#storyTitle').value.trim(),text=$('#storyText').value.trim();if(!title||!text)return;state.stories.unshift({title,text});persist();renderStories();$('#editor').close();e.target.reset();toast('攻略已保存在本机，可复制分享')};
$('#cityImage').src='https://images.unsplash.com/photo-1666361533726-53ede25fb728?auto=format&fit=crop&w=1600&h=900&q=85';$('#cityImage').alt='黄浦江对岸的上海浦东天际线，摄影 HAO SUN / Unsplash';render();const match=location.hash.match(/^#activity-(\d+)$/);if(match&&data.some(a=>a.id===+match[1]))detail(+match[1]);
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'filter_weekend_activities',description:'按兴趣筛选当前页面的周末活动。',inputSchema:{type:'object',properties:{category:{type:'string',enum:['全部','展览','市集','户外','演出']}},required:['category'],additionalProperties:false},execute(input){if(!['全部','展览','市集','户外','演出'].includes(input.category))throw Error('无效兴趣');category=input.category;document.querySelectorAll('[data-cat]').forEach(b=>b.classList.toggle('selected',b.dataset.cat===category));navigate('discover');return results().map(a=>({id:a.id,title:a.title,price:a.price}))}})).catch(()=>{})}catch{}}
